#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#define main legacy_main
#include "../background-subtract-cuda/main.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(int argc,char**argv){int n=65536,repeats=argc>1?atoi(argv[1]):20;std::vector<unsigned char> bn0(n),tn0(n,128),a(n),b(n),h1(n),h2(n),ebr,etr,expected,output,buf(n);for(int i=0;i<n;i++){bn0[i]=i%256;a[i]=(i/256)%256;b[i]=(i*29+11)%256;h1[i]=a[i];h2[i]=(i+1)%2?a[i]:255-a[i];if(i<256){bn0[i]=21;a[i]=141;b[i]=0;h1[i]=h2[i]=141;}}
ebr=bn0;etr=tn0;merge_ref(n,a.data(),h1.data(),h2.data(),etr.data(),ebr.data());merge_ref(n,b.data(),a.data(),h1.data(),etr.data(),ebr.data());for(int k=0;k<2;k++){expected.insert(expected.end(),ebr.begin(),ebr.end());expected.insert(expected.end(),etr.begin(),etr.end());}
unsigned char *da,*db,*dh1,*dh2,*bn,*tn,*mp;for(auto ptr:{&da,&db,&dh1,&dh2,&bn,&tn,&mp})CK(cudaMalloc(ptr,n));CK(cudaMemcpy(da,a.data(),n,cudaMemcpyHostToDevice));CK(cudaMemcpy(db,b.data(),n,cudaMemcpyHostToDevice));CK(cudaMemcpy(dh1,h1.data(),n,cudaMemcpyHostToDevice));CK(cudaMemcpy(dh2,h2.data(),n,cudaMemcpyHostToDevice));auto reset=[&](){CK(cudaMemcpy(bn,bn0.data(),n,cudaMemcpyHostToDevice));CK(cudaMemcpy(tn,tn0.data(),n,cudaMemcpyHostToDevice));CK(cudaDeviceSynchronize());};auto launch=[&](int mode,unsigned char*img,unsigned char*x,unsigned char*y){if(mode)merge<<<256,256>>>(n,img,x,y,tn,bn);else{findMovingPixels<<<256,256>>>(n,img,x,y,tn,mp);updateBackground<<<256,256>>>(n,img,mp,bn);updateThreshold<<<256,256>>>(n,img,mp,bn,tn);}};reset();for(int mode=0;mode<2;mode++){reset();launch(mode,da,dh1,dh2);launch(mode,db,da,dh1);}CK(cudaDeviceSynchronize());bool all=true;
for(int trial=1;trial<=5;trial++){double times[2]={};output.clear();for(int mode=0;mode<2;mode++){for(int rep=0;rep<repeats;rep++){reset();auto t0=std::chrono::steady_clock::now();launch(mode,da,dh1,dh2);launch(mode,db,da,dh1);CK(cudaDeviceSynchronize());times[mode]+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeats;}CK(cudaMemcpy(buf.data(),bn,n,cudaMemcpyDeviceToHost));output.insert(output.end(),buf.begin(),buf.end());CK(cudaMemcpy(buf.data(),tn,n,cudaMemcpyDeviceToHost));output.insert(output.end(),buf.begin(),buf.end());}
int ma=0;for(int i=0;i<4*n;i++)ma=std::max(ma,abs(int(output[i])-int(expected[i])));bool ok=ma==0;all&=ok;char file[100];sprintf(file,"background_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),1,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%d,\"max_rel_error\":0,\"timing_region\":\"sum_split_and_merged_two_frame_kernel_regions\",\"jit_excluded\":true,\"internal_repeats\":%d,\"mode_times_seconds\":[%.12g,%.12g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint8\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,times[0]+times[1],ok?"true":"false",4*n,ma,repeats,times[0],times[1],file,4*n);}
for(auto ptr:{da,db,dh1,dh2,bn,tn,mp})CK(cudaFree(ptr));puts(all?"PASS":"FAIL");return all?0:1;}
